const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const output=path.join(root,'verification');
const source=path.join(root,'AFTERLIGHT.html');
const expectedGameCount=26;
const desktopOnly=/^(1|true|yes)$/i.test(process.env.DESKTOP_ONLY||'');
const networkOnly=/^(1|true|yes)$/i.test(process.env.NETWORK_ONLY||'');
const reportName=networkOnly?'portable-network-report':'portable-report';
const assetManifest=JSON.parse(await readFile(path.join(root,'assets-manifest.json'),'utf8'));
assert.ok(Array.isArray(assetManifest.images)&&assetManifest.images.length>0,'Asset manifest must contain generated images');
const expectedAssetNames=assetManifest.images.map(image=>image.name).sort();
assert.equal(new Set(expectedAssetNames).size,expectedAssetNames.length,'Asset manifest names must be unique');
const isolated=await mkdtemp(path.join(tmpdir(),'afterlight-card-party-'));
const target=path.join(isolated,'AFTERLIGHT.html');
await copyFile(source,target);await mkdir(output,{recursive:true});
const base=pathToFileURL(target).href,bytes=await readFile(target);
const report={startedAt:new Date().toISOString(),source,isolatedDirectory:isolated,url:base,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex'),desktopOnly,method:`Exact standalone HTML copied alone into an isolated directory and opened by file://. Offline home, all ${expectedGameCount} arcade games, actual keyboard inputs, card board UI, ${desktopOnly?'desktop rendering diagnostics':'mobile touch'} and real public PeerJS/WebRTC. No source-module imports. Explicit deterministic hand/position/timing fixtures exercise edge cases; game countdown/time and board animation timers accelerate waiting.`,limits:['Four WebRTC peers share one computer. Separate WANs, restrictive NATs and TURN relays are not covered.','Timers and deterministic fixtures accelerate testing; these checks do not represent all catalog games as naturally timed full matches.',desktopOnly?'Desktop-only run: mobile layout and touch were deliberately not tested.':'Mobile layout and touch use Chrome device emulation at 390×844, not a physical phone.'],checks:[],skipped:[],pageErrors:[],consoleErrors:[],failedRequests:[],offlineExternalRequests:[],websockets:[],screenshots:[]};
let browser;const games=[],sceneDiagnostics=[];report.scope=networkOnly?'network-only':'full-desktop';if(networkOnly)report.method='Focused exact-HTML public PeerJS/WebRTC regression only. Four isolated file browsers exercise private cards, chained play, debt stacking/acceptance, shuffle order, actual six-button inputs, prediction with injected delay, seeded events, two challenges and points finish. No offline catalog or phone checks run in this scope.';
function observe(page,label,offline=false){page.on('pageerror',e=>report.pageErrors.push({label,message:e.message,stack:e.stack}));page.on('console',m=>{if(m.type()==='error')report.consoleErrors.push({label,message:m.text()})});page.on('requestfailed',r=>report.failedRequests.push({label,url:r.url().split('?')[0],error:r.failure()?.errorText}));page.on('request',r=>{if(offline&&!r.url().startsWith('data:')&&!r.url().startsWith('blob:')&&r.url()!==base)report.offlineExternalRequests.push(r.url())});page.on('websocket',s=>report.websockets.push({label,url:s.url().split('?')[0]}));page.on('dialog',d=>d.dismiss());}
async function check(name,fn){try{const details=await fn();report.checks.push({name,passed:true,details});console.log('PASS',name);return details}catch(e){report.checks.push({name,passed:false,error:e.stack||e.message});console.error('FAIL',name,e.message);return null;}}
async function ready(page){await page.goto(base,{waitUntil:'load'});await page.waitForFunction(expected=>window.afterlight?.minigames?.length===expected&&window.afterlight.titleCast?.characters?.length===4,expectedGameCount,{timeout:25000});}
async function arcade(page){await page.locator('[data-nav="arcade"]').first().click();await page.waitForSelector('.game-card');}
async function start(page,index){await page.locator(`[data-practice="${index}"]`).click();await page.locator(`[data-character="${index%8}"]`).click();await page.locator('#player-name').fill('Portable QA');await page.locator('#start-solo').click();await page.waitForSelector('#begin-minigame');assert.equal(await page.evaluate(()=>window.afterlight.state.phase),'minigame-intro');await page.locator('#begin-minigame').click();await page.waitForFunction(()=>window.afterlight.state.phase==='minigame'&&window.afterlight.state.game);await page.evaluate(()=>window.afterlight.state.countdown=0);await page.waitForFunction(()=>!document.querySelector('.stage-overlay'));await page.locator('#game-canvas').click();}
async function press(page,key,ms=160){await page.keyboard.down(key);await page.waitForTimeout(ms);await page.keyboard.up(key);await page.waitForTimeout(40);}
async function finish(page){await page.evaluate(()=>{const s=window.afterlight.state;s.countdown=0;s.game.time=s.game.duration;});await page.waitForFunction(()=>window.afterlight.state.phase==='results');}
async function nativeOversizedRift(host){
 const receipt=await host.evaluate(()=>{
  const a=window.afterlight,s=a.state,g=s.game,n=a.network,pred=a.prediction;
  if(g?.id!=='rift-rumble'||!pred?.authoritative||!n.stateProjector)throw new Error('Missing native authority fixture');
  s.countdown=0;g.done=false;g.state.effects=[];g.state.hitstop=0;g.rng=513;
  const attacksBefore=g.state.attacks;
  for(const [i,p]of g.players.entries())Object.assign(p,{bot:false,x:420+i*20,y:430,vx:0,vy:0,ground:0,jumps:0,facing:1,damage:0,invuln:0,stun:0,attack:0,cooldown:0,specialAnimation:'',specialTime:0,specialCooldown:0,eliminated:false,respawn:0,prev:{}});
  pred.clear();pred.setGame(g,g.netId);
  for(const p of g.players)pred.setInput(p.id,{action:true},(n.inputSequences.get(p.id)||0)+1);
  pred.advance(1/60);
  const receipt={attacksBefore,attacks:g.state.attacks,effects:g.state.effects.length,recipientBytes:n.players.filter(p=>p.id!==n.id).map(p=>({id:p.id,bytes:new TextEncoder().encode(JSON.stringify(n.stateProjector(s,p.id))).byteLength}))};
  n.snapshotBases.clear();if(!n.broadcast(s))throw new Error('Native oversized snapshot rejected');
  g.time=g.duration;pred.clear();return receipt;
 });
 assert.ok(receipt.attacks-receipt.attacksBefore>=4,'All four normal attacks generated native effects');assert.equal(receipt.effects,100,'Native strikes fill the existing effect cap');assert.ok(receipt.recipientBytes.every(p=>p.bytes>16300),'Every private recipient view exceeds the old JSON limit');
 return {...receipt,method:'Clustered unprotected fighters perform one ordinary production attack tick; native bounded effects generate the oversized packet. Stored private projector and public broadcast path remain in use; no padding or fabricated effects.'};
}
