async function fixture(page,{hand,position=0,activeColor='ivory',top=card('top','ivory','9'),deck,turnIndex=0,stage='await-card',turnsCompleted=0}){
 await page.evaluate(({hand,position,activeColor,top,deck,turnIndex,stage,turnsCompleted})=>{
 const s=window.afterlight.state,p=s.players[turnIndex];s.phase='board';s.boardStage=stage;s.turnIndex=turnIndex;s.currentPlayerId=p.id;s.turnDirection=1;s.turnsCompleted=turnsCompleted;s.activeColor=activeColor;s.discard=[top];s.winnerId=null;s.finisherId=null;s.finishBonus=0;s.pendingEvent=null;s.storyEvent=null;s.boardEncounter=null;s.boardEncounters=[];s.lapCelebration=null;s.padEvent=null;s.drawnCardId=null;s.skipNext=false;s.pathOptions=[];s.transport=null;s.moveTarget=null;s.movesRemaining=0;s.moveTotal=0;s.chainValue=null;s.chainCount=0;s.pendingDraw=0;s.pendingDrawValue=null;s.turnOrder=s.players.map(p=>p.id);s.turnOrderRevision=0;s.timer=999;s.message='QA fixture '+Math.random();s.players.forEach(other=>{other.bot=false;other.hand?.forEach(c=>delete c.buff);});p.position=position;p.fromPosition=position;p.hand=hand;p.handCount=hand.length;p.calledLast=false;p.shortcutChoice=null;p.boost=0;
 if(deck){s.deck=deck;s.deckCount=deck.length;}delete s.game;
 },{hand,position,activeColor,top,deck,turnIndex,stage,turnsCompleted});
 await page.waitForTimeout(80);
}
